// Parse incoming WhatsApp message
const body = $input.first().body;
const from = body.From || body.from;
const text = body.Body || body.body;
const messageId = body.MessageSid || body.messageId;

return {
  phone: from.replace('whatsapp:', ''),
  message: text,
  messageId: messageId,
  timestamp: new Date().toISOString(),
  channel: 'whatsapp'
};

// Map phone to tenant (from DB or config)
// In production, query Supabase for phone→tenant mapping
const phoneToTenant = {
  '+5491234567890': 'tenant-demo',
  '+5491111111111': 'tenant-test'
};

const tenant = phoneToTenant[$json.phone] || 'tenant-default';

return {
  ...$json,
  tenantSlug: tenant
};

// Process response from BBC
const response = $json.body || $json;
const message = response.output || response.text || 'No se pudo procesar el mensaje';
const actions = response.suggestedActions || [];

return {
  phone: $input.last().json.phone,
  messageId: $input.last().json.messageId,
  bbcResponse: message,
  actions: actions,
  timestamp: new Date().toISOString()
};

